import collections, json
from common import ROOT, save, run
base=ROOT/'E4';r=json.loads((base/'results.json').read_text());rows=r['component_occurrences'];checked=[x for x in rows if x['status']=='CHECKED']
summary={'candidate_urls':len(r['downloads']),'downloaded':sum(d['status']=='DOWNLOADED' for d in r['downloads']),'unavailable':[{k:d.get(k) for k in ['id','url','http_status','error']} for d in r['downloads'] if d['status']!='DOWNLOADED'],
 'component_occurrences':len(rows),'outcome_counts':dict(collections.Counter(x['status'] for x in rows)),'new_canonical_graphs':len({x['canonical_graph_sha256'] for x in checked}),
 'structural_counts':dict(collections.Counter(x.get('structural_status') for x in checked)),'compile_counts':dict(collections.Counter(x.get('compile_status') for x in checked)),
 'semantic_counts':dict(collections.Counter(x.get('semantic_check') for x in checked)),
 'decoder_category_pass_components':sum(isinstance(x['decoder_check'],list) and all(d['status']=='PASS' for d in x['decoder_check']) for x in checked),
 'decoder_category_incompatible_components':sum(isinstance(x['decoder_check'],list) and any(d['status']=='FAIL' for d in x['decoder_check']) for x in checked),
 'decoder_inapplicable_components':sum(x['decoder_check']=='INAPPLICABLE_NO_GENERATED_CATEGORY_PATH' for x in checked),
 'decoder_dynamic_abstentions':sum(x['decoder_check']=='ABSTAIN_DYNAMIC_OUTPUT' for x in checked),
 'existing_generator_warnings':[{k:x[k] for k in ['candidate','component_sha256']}|{'diagnostic':x['checker']['generation']['diagnostics']} for x in checked if x['checker'].get('generation',{}).get('diagnostics')],
 'fresh_runtime_invocations':0,'established_new_reference_backed_semantic_defects':0,'established_new_supported_end_to_end_failures':0,
 'claim_boundary':'Static external application with semantic abstention. No supported end-to-end natural defect is established; no statement that the artifacts are defect-free.'}
q=run(['git','diff','--exit-code','HEAD','--'],base/'freeze-logs/post-experiment-diff',cwd=base/'protocol');assert q.returncode==0
summary['tracked_frozen_files_unchanged']=True;save(base/'summary.json',summary)
lines=['# E4 results','',f"The fixed 20 candidate URLs yielded {summary['downloaded']} successful downloads and {len(summary['unavailable'])} unavailable candidates. Recursive extraction produced {len(rows)} component occurrences. One prior component and two prior-graph occurrences were excluded, leaving {summary['new_canonical_graphs']} new canonical groups. No failed candidate was replaced.",'',f"All {len(checked)} were structurally accepted. Raw generated Java compiled for {summary['compile_counts'].get('PASS',0)} and failed for {summary['compile_counts'].get('FAIL',0)}. The frozen D rule reports {summary['decoder_category_pass_components']} compatible category paths, {summary['decoder_category_incompatible_components']} incompatible category paths, and {summary['decoder_inapplicable_components']} without that category path. All semantic checks abstain for lack of an independently supplied artifact-tied reference.",'', '| Candidate | Component | S | Raw javac | Frozen D | Existing warning |','|---|---|---|---|---|---|']
for x in checked:
 d=x['decoder_check'];status='/'.join(v['status'] for v in d) if isinstance(d,list) else d
 lines.append(f"| {x['candidate']} | `{x['component_sha256'][:12]}` | {x['structural_status']} | {x['compile_status']} | {status} | {'Non-RGB unsupported fallback' if x['checker'].get('generation',{}).get('diagnostics') else 'None recorded'} |")
lines+=['','## Negative and scoped outcomes','', 'Five D-incompatible detector wrappers fail raw javac before a generated runtime path can be exercised. Four D-incompatible segmentation wrappers compile, but each generator explicitly warns that its non-RGB output is unsupported and is treated as a numeric tensor. They are preserved as static consumer-compatibility findings, not silently accepted supported-interface defects. Two Pose wrappers have no applicable generated category getter and fail javac.','', 'No new reference-backed semantic mismatch or supported end-to-end natural failure is established. No runtime execution was performed on the external originals; compatible D results are static precondition checks, not confirmations of end-to-end execution or semantic correctness. No precision/recall or prevalence estimate is reported.','', 'Unavailable candidate addresses (all retained):','']
for d in summary['unavailable']:lines.append(f"- {d['id']}: HTTP {d['http_status']}; `{d['url']}`")
lines+=['',f"Frozen protocol commit: `{r['protocol_commit']}`. Tracked frozen rule/protocol files remain unchanged after execution. The collected data uses the local same-session freeze, not a third-party registration or independent human review. Candidate URL construction was not verification of publisher-catalog existence.",'', 'Exact models, source URLs, shapes/signatures, raw checker output, emitted Java, javac logs/classes and exclusions are in E4/results.json and its artifact paths. The raw checker reports are preserved even when a scope filter would abstain. Dynamic-output abstentions and absent-metadata counts happen to be zero in the included set; that is not a rule to omit them from future studies.','']
(ROOT/'EXPERIMENT_E4_RESULTS.md').write_text('\n'.join(lines));print(json.dumps(summary,indent=2))
